    AzkarItem(text = "أصبحنا و أصبح الملك لله و الحمدلله، لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء، قدير ربي أسألك خير ما في هذا اليوم و خير ما بعده، و أعوذ بك من شر ما في هذا اليوم و شر ما بعده، رب أعوذ بك من الكسل و سوء الكبر، رب أعوذ بك من عذاب في النار و و عذاب في القبر", count = 1),
    AzkarItem(text = "اللهم إني أسألك علماً نافعاً، و رزقاً طيباً، و عملاً متقبلاً", count = 1),
