    AzkarItem(text = "اللهم إني أسألك العفو و العافية في الدنيا و الآخرة، اللهم إني أسألك العفو و العافية في ديني و دنياي و أهلي و مالي، اللهم أستر عوراتي و أمن روعاتي، اللهم إحفظني من بين يدي و من خلفي ، و عن يميني و عن شمالي، و من فوقي، و أعوذ بعظمتك أن أغتال من تحتي.", count = 1),
