    AzkarItem(text = "أصبحنا على فطرة الإسلام، و على كلمة الإخلاص، و على دين نبينا محمد صلى الله عليه وسلم، و على ملة أبينا إبراهيم حنيفاً مسلماً و ما كان من المشركين", count = 1),
